Create a Swift method to sort a dictionary alphabetically.

### Input:
Dictionary - key1: value1, key2: value2, key3: value3

### Response:
func sort(dict: [String: String]) -> [String: String] {
    let sortedKeys = dict.keys.sorted { $0 < $1 }
    var sortedDict = [String: String]()
    for key in sortedKeys {
        sortedDict[key] = dict[key]
    }
    return sortedDict
}

### Instruction:
Write a module in Rust to identify palindromic strings.

### Response:
fn is_palindrome(target: &str) -> bool {
    let mut char_vec: Vec<char> = target.chars().collect();
    char_vec.reverse();
    let reversed_target: String = char_vec.into_iter().collect();
    if target == reversed_target {
        return true;
    }
    return false;
}

