def modify_dict_items(dictionary: dict, index: int) -> dict:

    """
    Given a dictionary and an index, modify the value of each item in the dictionary by subtracting the index.

    Args:
    - dictionary (dict): A dictionary containing integer keys and corresponding values
    - index (int): The integer value to be subtracted from each item value in the dictionary

    Returns:
    - dict: The modified dictionary with updated values

    Example:
    modify_dict_items({'A': 5, 'B': -3, 'C': 10}, 2) -> {'A': 3, 'B': -5, 'C': 8}
    modify_dict_items({'X': 100, 'Y': -50, 'Z': 0}, -5) -> {'X': 105, 'Y': -45, 'Z': 5}
    """

### Solution:


    if index < 0:
        # Subtracting negative integers is equivalent to adding a positive integer
        index = abs(index)

    modified_dict = {}
    for key, value in dictionary.items():
        if isinstance(value, int):
            modified_dict[key] = value - index

    return modified_dict

