### Problem:
def modify_nested_list(nested_list: List[List[int]], row: int, col: int, value: int) -> List[List[int]]:
    """
    Modify a specific value in a nested list at the given row and column index.

    Args:
    nested_list (List[List[int]]): The nested list to be modified.
    row (int): The row index of the element to be modified.
    col (int): The column index of the element to be modified.
    value (int): The new value to be assigned to the element.

    Returns:
    List[List[int]]: The modified nested list.

    """

### Solution:

    if row < 0 or row >= len(nested_list) or col < 0 or col >= len(nested_list[row]):
        return nested_list  # Invalid indices, return the original nested list as it is
    else:
        return [
            [
                nested_list[i][j] if i != row or j != col else value 
                for j in range(len(nested_list[i]))
            ] 
            for i in range(len(nested_list))
        ]

