def modify_dish_items(chef_dict: dict, dish_name: str, ingredient: str, quantity: int):
    """
    This function modifies the ingredient and its quantity for a specific dish in the chef's dictionary.

    Args:
    - chef_dict (dict): A dictionary containing the chef's dishes and ingredients with their respective quantities.
    - dish_name (str): The name of the dish to modify.
    - ingredient (str): The name of the ingredient to modify for the given dish.
    - quantity (int): The new quantity of the ingredient for the given dish.

    Returns:
    - None: The function modifies the chef's dictionary in-place.

    """

### Solution:

    if dish_name in chef_dict:
        for i, (dish, ingredients) in enumerate(chef_dict.items()):
            if dish == dish_name:
                for j, (ingr, quant) in enumerate(ingredients.items()):
                    if ingr == ingredient:
                        chef_dict[dish][ingr] = quantity
                        return
                else:
                    chef_dict[dish_name][ingredient] = quantity
                    return
    else:
        chef_dict[dish_name] = {
            ingredient: quantity
        }

